<?php
$files = [
    'manifest.json' => '',
    'assets/app-DFAQ3oYN.css' => '',
    'assets/fonts-DkuEHybc.css' => '',
];
$buildDir = __DIR__ . '/build';
if (!is_dir($buildDir)) mkdir($buildDir, 0777, true);
if (!is_dir($buildDir . '/assets')) mkdir($buildDir . '/assets', 0777, true);
foreach ($files as $path => $b64) {
    file_put_contents($buildDir . '/' . $path, base64_decode($b64));
}
echo "Build files created successfully!\n";
